<script setup lang="ts">
import { computed } from 'vue'
import ActionMenu from './ActionMenu.vue'
import CategoryIcon from './CategoryIcon.vue'
import UiIcon from './UiIcon.vue'
import { localDay, money } from './ledgerViewModels'
import {statisticsSummary,transactionShareAmount,transactionInStatistics,type Book,type Category,type Transaction} from './ledger'
const props=withDefaults(defineProps<{transactions:Transaction[];categories:Category[];books:Book[];deleteLabel?:string;statisticsBookId?:string}>(),{deleteLabel:'删除流水'})
const emit=defineEmits<{edit:[tx:Transaction];delete:[tx:Transaction]}>()
const categoriesById=computed(()=>new Map(props.categories.map(category=>[category.id,category])))
const booksById=computed(()=>new Map(props.books.map(book=>[book.id,book])))
const groups=computed(()=>{
  const map=new Map<string,Transaction[]>()
  for(const tx of [...props.transactions].sort((a,b)=>b.happenedAt.localeCompare(a.happenedAt))){const date=localDay(new Date(tx.happenedAt));map.set(date,[...(map.get(date)||[]),tx])}
  const today=localDay(new Date()),yesterday=new Date();yesterday.setDate(yesterday.getDate()-1)
  return [...map].map(([date,rows])=>({date,rows,label:date===today?'今天':date===localDay(yesterday)?'昨天':new Date(`${date}T12:00:00`).toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short',...(date.slice(0,4)!==String(new Date().getFullYear())?{year:'numeric' as const}:{})}),...statisticsSummary(rows,props.statisticsBookId)}))
})
function tags(tx:Transaction){return[...(!transactionInStatistics(tx,props.statisticsBookId)?[{text:'不计统计',book:false}]:[]),...tx.bookIds.map(id=>({text:booksById.value.get(id)?.name||'已删除账本',book:true})),...(tx.paymentMethod?[{text:tx.paymentMethod,book:false}]:[]),...(tx.source==='ocr'?[{text:'截图记账',book:false}]:[]),...(tx.installmentMonths&&tx.installmentMonths>1?[{text:`分期 ${tx.installmentMonths} 期`,book:false}]:[])]}
function time(value:string){return new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
</script>
<template>
  <div class="ledger-view tl-days">
    <section v-for="group in groups" :key="group.date" class="tl-day"><header><div><b>{{ group.label }}</b><small>{{ group.rows.length }} 笔</small></div><div class="tl-day-totals"><span v-if="group.expense">支出 <b>{{ money(group.expense) }}</b></span><span v-if="group.income">收入 <b>{{ money(group.income) }}</b></span></div></header>
      <div class="tl-group"><article v-for="tx in group.rows" :key="tx.id" class="tl-row"><button type="button" class="tl-open" :aria-label="`编辑流水${tx.title}`" @click="emit('edit',tx)"><span class="tl-icon" :style="{'--tx-color':categoriesById.get(tx.categoryId||'')?.color||(tx.kind==='expense'?'#d98a5c':'#429e81')}"><CategoryIcon :name="categoriesById.get(tx.categoryId||'')?.icon" :category-name="categoriesById.get(tx.categoryId||'')?.name" :flow-type="tx.kind" :color="categoriesById.get(tx.categoryId||'')?.color||'currentColor'" :size="20"/></span><span class="tl-copy"><strong>{{ tx.title }}</strong><small>{{ categoriesById.get(tx.categoryId||'')?.name||'未分类' }}<span v-if="tx.merchant"> · {{ tx.merchant }}</span> · {{ time(tx.happenedAt) }}</small><span v-if="tags(tx).length" class="tl-tags"><span v-for="(tag,index) in tags(tx).slice(0,3)" :key="`${index}-${tag.text}`" :class="{book:tag.book}">{{ tag.text }}</span><span v-if="tags(tx).length>3" :title="tags(tx).slice(3).map(tag=>tag.text).join('、')">+{{ tags(tx).length-3 }}</span></span></span><span class="tl-money"><b :class="tx.kind==='expense'?'lv-expense':'lv-income'">{{ tx.kind==='expense'?'−':'+' }}{{ money(tx.amount,tx.currency||'CNY') }}</b><small v-if="transactionInStatistics(tx,statisticsBookId)&&Math.abs(transactionShareAmount(tx,statisticsBookId)-tx.amount)>.000001" class="tl-personal-share">本人 {{ money(transactionShareAmount(tx,statisticsBookId),tx.currency||'CNY') }}</small><small v-if="tx.discountAmount">优惠 {{ money(tx.discountAmount) }}</small><small v-else-if="tx.premiumAmount">溢价 {{ money(tx.premiumAmount) }}</small></span></button><ActionMenu :label="`${tx.title}的更多操作`" :actions="[{id:'edit',label:'编辑流水',icon:'edit'},{id:'delete',label:deleteLabel,icon:'trash',danger:true}]" @select="$event==='edit'?emit('edit',tx):emit('delete',tx)"/></article></div>
    </section>
    <div v-if="!groups.length" class="tl-empty"><UiIcon name="list" :size="29"/><b>还没有流水</b><p>记下第一笔收支后，记录会显示在这里。</p></div>
  </div>
</template>
<style scoped>
.tl-days{display:grid;grid-template-columns:minmax(0,1fr);min-width:0;max-width:100%;gap:22px;}.tl-day{min-width:0;max-width:100%;}.tl-day>header{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 3px 10px;}.tl-day>header>div:first-child{display:flex;align-items:center;gap:8px;}.tl-day>header b{font-size:12px;font-weight:650;}.tl-day>header small{color:var(--lv-muted);font-size:10px;}.tl-day-totals{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:5px 12px;color:var(--lv-muted);font-size:10px;}.tl-day-totals b{font-size:10px!important;font-weight:500!important;color:var(--lv-ink);}.tl-group{border:1px solid var(--lv-line);border-radius:18px;background:var(--lv-paper);}.tl-row{position:relative;display:flex;align-items:center;gap:4px;min-width:0;padding:9px 10px 9px 13px;border-bottom:1px solid var(--lv-line);}.tl-row:last-child{border-bottom:0;}.tl-row:first-child{border-radius:18px 18px 0 0;}.tl-row:last-child{border-radius:0 0 18px 18px;}.tl-row:only-child{border-radius:18px;}.tl-row:hover{background:color-mix(in srgb,var(--lv-soft) 55%,var(--lv-paper));}
.tl-open{display:flex;align-items:center;gap:12px;min-width:0;flex:1;min-height:63px;padding:4px 2px;border:0;border-radius:11px;background:transparent;color:var(--lv-ink);text-align:left;font-family:inherit;cursor:pointer;}.tl-open:focus-visible{outline:2px solid var(--lv-accent);outline-offset:3px;}.tl-icon{display:grid;place-items:center;width:41px;height:41px;flex:none;border-radius:15px;background:color-mix(in srgb,var(--tx-color) 12%,var(--lv-paper));color:var(--tx-color);}.tl-copy{display:flex;flex-direction:column;gap:6px;min-width:0;flex:1;}.tl-copy>strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;font-weight:600;}.tl-copy>small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:var(--lv-muted);}.tl-tags{display:flex;flex-wrap:wrap;gap:4px;}.tl-tags>span{max-width:110px;overflow:hidden;padding:3px 6px;border-radius:6px;background:var(--lv-soft);color:var(--lv-muted);font-size:9px;text-overflow:ellipsis;white-space:nowrap;}.tl-tags>span.book{background:color-mix(in srgb,var(--lv-accent) 9%,var(--lv-paper));color:var(--lv-accent);}.tl-money{display:flex;align-items:flex-end;flex-direction:column;gap:7px;flex:none;max-width:42%;margin-left:5px;}.tl-money b{overflow-wrap:anywhere;text-align:right;font-size:14px;font-weight:650;font-variant-numeric:tabular-nums;letter-spacing:-.2px;}.tl-money small{font-size:9px;color:var(--lv-muted);}.tl-empty{display:flex;align-items:center;flex-direction:column;gap:13px;padding:35px 18px;border:1px dashed var(--lv-line);border-radius:18px;background:var(--lv-paper);color:var(--lv-muted);text-align:center;}.tl-empty>b{font-size:13px;color:var(--lv-ink);}.tl-empty>p{margin:0;font-size:11px;}
@media(max-width:600px){.tl-day>header{align-items:flex-start;}.tl-day-totals{font-size:9px;}.tl-day-totals b{font-size:9px!important;}.tl-row{padding:8px 6px 8px 10px;gap:2px;}.tl-open{gap:9px;}.tl-icon{width:35px;height:35px;border-radius:12px;}.tl-copy>strong{font-size:14px;}.tl-copy>small{font-size:10px;}.tl-money b{font-size:14px;}.tl-money{margin-left:2px;max-width:38%;}.tl-row :deep(.lv-menu-trigger){min-width:28px;min-height:32px;padding:5px;}.tl-tags>span{max-width:86px;font-size:9px;padding:2px 5px;}}
</style>
